  "intro": [
   "2024年，浦东美术馆携手西班牙普拉多国家博物馆，举办了国内迄今规模最大的普拉多博物馆藏品展。这次展览可以说是国内近年来最重磅的西方艺术展览之一，全球仅此一站。相信很多朋友还没看过这个展览，整理了以前拍的照片，分享给大家。",
   "普拉多博物馆位于西班牙马德里，被认为是全世界最好的艺术博物馆之一。博物馆藏品以西班牙王室收藏为基础，聚焦欧洲艺术主题，囊括12世纪起至20世纪初的欧洲艺术精品，尤以西班牙黄金时代的经典画作和尼德兰艺术见长，可以说是16-17世纪西班牙黄金时代的艺术见证。",
   "本次展览汇集普拉多博物馆的 70 件油画真迹，加上专题展厅的一件素描，共 71 件作品。本虚拟展厅按 5 大板块、12 个单元铺开，并附创作年代时间轴、艺术家与流派索引、艺术家关系图与观展指南。"
  ],
