     "id": "e007",
     "order": 5,
     "name": "伊丽莎白·德·瓦卢瓦手握费利佩二世肖像",
     "artist": "索福尼斯巴·安圭索拉",
     "artistId": "anguissola",
     "year": 1561,
     "yearLabel": "1561–1565 年",
     "school": "文艺复兴（意大利）",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "索福尼斯巴·安圭索拉（1532-1625？，克雷莫纳-巴勒莫），《伊丽莎白·德·瓦卢瓦手握费利佩二世肖像》，1561-1565年，来自王室收藏。",
      "费利佩二世的宫廷吸引了一批欧洲最重要的肖像画家。而索福尼斯巴·安圭索拉尤其特殊，因为当时，女性投身绘画领域非常罕见。事实上，她以费利佩二世的第三位妻子——伊丽莎白·德·瓦卢瓦（1546-1568年）王后女官的身份来到马德里。",
      "在宫廷中，安圭索拉创作了大量肖像画，不仅展示了她的卓越才华，也体现了她对一些同时代画家创作的王室肖像画的理解，并在此作中承续了这种传统。她的笔触细腻，能精确表现华美服饰的富丽，与当时男性更为朴素的风尚形成鲜明对比。"
     ],
