     "intro": [
      "马里纳斯·凡·雷梅尔思维勒（约1489-约1546，雷默斯瓦尔-胡斯？），《税吏与他的妻子》（又名《兑币商和妻子》），1539年，由德尼亚及塔里法公爵遗孀玛丽亚·德·洛斯·安赫莱斯·梅迪纳于1934年遗赠。",
      "这位尼德兰画家常以讽刺和道德批判的视角，描绘上层商业资产阶级。他的画作深刻批评了当时金融世界的贪婪和欲望——尤其指向了兑币商和税吏。他卓越的绘画技艺让作品的众多细节生动逼真，如这幅画中细腻描绘的称重钱币的场景。"
     ],
