     "id": "e009",
     "order": 7,
     "name": "画家一家",
     "artist": "雅各布·乔登斯",
     "artistId": "jordaens",
     "year": 1621,
     "yearLabel": "约 1621–1622 年",
     "school": "佛兰德斯巴洛克",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "雅各布·乔登斯（1593-1678，安特卫普），《画家一家》，约1621-1622年，来自王室收藏。",
      "这幅画作是普拉多博物馆17世纪佛兰德斯画派藏品中最引人注目的肖像画之一，其创作者雅各布·乔登斯与鲁本斯、凡·戴克及老扬·勃鲁盖尔齐名，这是博物馆佛兰德斯绘画中为数不多的一幅群像，忠实反映了当时的资产阶级社会风貌。",
      "画家将自己描绘成手持鲁特琴而非手握画笔的形象，展现了其社会地位。他和妻子身着华服，身边还有一位女佣，这彰显了他们优渥的经济条件。尽管画中融入了众多与家庭有关的象征，但乔登斯并未像其他佛兰德斯画家那样采用常见的理想化风格。面容和肤色展现出画家在创作人物时对色彩强度和极致真实的追求。"
     ],
