   "id": "r03",
   "chapter": "第一板块 · 序厅与王权",
   "title": "奇特的人物：俳优",
   "subtitle": "Los bufones de la corte",
   "section": 1,
   "sectionColor": "#c9a45c",
   "intro": [
    "奇特的人物：俳优",
    "俳优的职责是供国王和贵族取乐，他们通常带有某些身心缺陷。在现代历史早期，俳优是西班牙宫廷的显著特色之一。正因如此，普拉多博物馆珍藏有大量此类人物的肖像。委拉斯开兹对这一题材进行过深入探索，相较于其他肖像画作，他在创作俳优画时拥有更大的自由度，此类肖像的成功之作，为后来的马德里画家提供了参照，从《俳儒和狗》便可得见此前杰作的影子。",
    "巴洛克艺术时期，对长相奇特人物的刻画不仅限于俳优，也包括“胡须女”“巨人”等特殊群体，这不仅源自人们的猎奇心理，还包含了道德教化和警世劝诫的深层意义。"
   ],
