     "id": "e010",
     "order": 1,
     "name": "佩尼亚兰达长胡子的女人",
     "artist": "胡安·桑切斯·科坦",
     "artistId": "cotan",
     "year": 1590,
     "yearLabel": "1590 年",
     "school": "西班牙巴洛克",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "胡安·桑切斯·科坦（1560-1627，托莱多省奥尔加斯市-格拉纳达），《佩尼亚兰达长胡子的女人》，1590年，来自王室收藏。",
      "画中的这位女性——布里吉达·德尔里奥，在16世纪末成为了广受关注的对象，原因在于她长出了男性般的胡须。此作意在传播这种罕见现象，该现象也成为了《堂吉诃德》第二部中的一则滑稽情节。古怪之余，这种现象也被认为是放纵和魔鬼侵扰的结果，因而这幅作品还带有道德教化意味。"
     ],
