     "workCount": 1,
     "intro": [
      "弗朗西斯科·德·苏巴朗（传）（1598-1664，巴达霍斯省丰特德坎托斯市-马德里），《巨型头像》，约1635年，来自王室收藏。",
      "这幅作品因卓越品质和独特图像学特征在普拉多博物馆中独具特色，在其他收藏中也难得一见。这可能是在描绘一个巨人。在古希腊和古罗马文化中，这类神话中的生物通常被描绘成粗暴的形象，令人恐惧。因此，这件作品的尺幅远超真人大小的，人物的面部表情也体现出他的巨大力量。",
      "光线的强烈对比、脸部特征的着重刻画以及颜料的厚重质感，都属于苏巴朗的绘画风格。他是一位来自埃斯特雷马杜拉的画家，曾在1634年前后为费利佩四世效力。研究表明，这幅画作原本置于王宫内，与俳优画相邻，初衷也是为了加强对人物奇特外貌的展现。"
     ],
