     "order": 3,
     "name": "俳优卡拉巴西亚斯",
     "artist": "迭戈·委拉斯开兹",
     "artistId": "velazquez",
     "year": 1638,
     "yearLabel": "约 1638 年",
     "school": "西班牙巴洛克",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "迭戈·委拉斯开兹，《俳优卡拉巴西亚斯》，约1638年，来自王室收藏。",
      "这幅作品是委拉斯开兹最著名的俳优画之一。这些人物给了画家更多自由描绘的空间。这可以从俳优的微笑和不同寻常的姿势中看出，而在贵族和王室肖像画中，这样的表现是绝不允许的，因为可能被视为有失体面。",
      "委拉斯开兹在这幅画中运用了他最为娴熟的肖像画技巧，如对空间的模糊处理和对头部的轻微虚化。这幅画也是毕加索1895年首次造访普拉多博物馆时临摹的作品之一。"
     ],
