     "workCount": 1,
     "intro": [
      "委拉斯开兹的追随者，《俳儒和狗》，约1640年，来自王室收藏。",
      "这幅肖像画彰显了委拉斯开兹对马德里画家们的深远影响。他的追随者娴熟模仿其技法来创造空间深度，尤其是通过明暗的巧妙运用，正如这幅画作所示。作品中狗的体型与画中人的矮小身材形成对比，反映出大多数宫廷俳优都存在某种身体缺陷。此外，他的华丽服饰，在西班牙巴洛克绘画的男性服装中显得尤为独特。"
     ],
