   "id": "r04",
   "chapter": "第一板块 · 序厅与王权",
   "title": "波旁王朝与新政权",
   "subtitle": "Los Borbones en España",
   "section": 1,
   "sectionColor": "#c9a45c",
   "intro": [
    "波旁王朝与新政权",
    "哈布斯堡王朝最后一任君主卡洛斯二世去世后，费利佩五世继承王位，从而开启了波旁王朝在西班牙的统治。这一时期，得益于数代君主引入的众多画家，见证了绘画风格与视觉表达方面的创新浪潮。"
   ],
   "knowledge": [
    {
     "term": "波旁王朝",
     "text": "1700 年，哈布斯堡王朝最后一任君主卡洛斯二世去世，法国波旁家族的费利佩五世继位。法国画家、宫廷礼仪与家族肖像传统随之进入西班牙。"
    },
    {
     "term": "新古典主义",
     "text": "门斯把温克尔曼式的明晰、素雅与理想化带入西班牙宫廷。他追求明晰的空间和素雅的装饰，尤其注重捕捉人物个性，影响了戈雅一代。"
    }
   ],
