     "id": "e014",
     "order": 1,
     "name": "费利佩五世一家",
     "artist": "让·朗克",
     "artistId": "ryck",
     "year": 1723,
     "yearLabel": "约 1723 年",
     "school": "洛可可",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "让·朗克（1674-1735，蒙彼利埃-马德里），《费利佩五世一家》，约1723年，来自王室收藏。",
      "随着波旁王朝的入主，法国画家也来到西班牙，让·朗克就是其中最早的一批。新的风格和图像语言得以融入西班牙绘画，例如家族肖像。此前，这一体裁在西班牙并不常见。",
      "此作虽为一幅大尺幅画作的草图或预备作品，但画家已精心设计了人物布局、色彩和光影的搭配。画中的费利佩五世和埃丽莎贝塔·法尔内塞王后坐姿端庄，孩子们围绕在两人周围，以此向新臣民昭示王位继承权的归属。"
     ],
