     "id": "e017",
     "order": 4,
     "name": "红衣主教路易斯·玛丽亚·德·波旁-瓦拉布里加",
     "artist": "弗朗西斯科·德·戈雅",
     "artistId": "goya",
     "year": 1802,
     "yearLabel": "约 1802 年",
     "school": "浪漫主义",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "弗朗西斯科·德·戈雅·卢西恩特斯，《红衣主教路易斯·玛丽亚·德·波旁-瓦拉布里加》，约1802年，1906年入藏。",
      "画中人是王子路易斯·安东尼奥·德·波旁（1727-1785年）之子，生于1777年。路易斯·安东尼奥是卡洛斯三世的弟弟。遵循西班牙王室数世纪以来的传统，一些王室成员投身教会并担任要职。1800年，路易斯·玛丽亚被封为红衣主教和托莱多大主教——西班牙教会最显赫的职务。他在西班牙独立战争（1808-1814年）期间发挥了关键作用，推动了若干改革，并在费尔南多七世复位前暂时摄政。",
      "戈雅绘制这幅肖像时已身为宫廷画师。他继承了委拉斯开兹在王室肖像中推广的模式，并在其他作品中多次实践：人物从暗色的背景中突显出来，周遭既无空间参照，亦无装饰物。戈雅同时承袭了门斯创作《萨克森的玛丽亚·阿玛莉亚》时的技巧，通过打开的书本，为画作营造出瞬时感。"
     ],
