   "intro": [
    "日常生活中的神圣图像",
    "17世纪的西班牙绘画尤其注重宗教和神话题材的日常化，这一趋势受到了意大利自然主义风潮的影响。因此，画家们通常选择普通人作为模特，摒弃了对人物特征的理想化处理，并以当时流行的服饰替代了神话或宗教故事中设定的古代装扮。同时，这些形象常被置于朴素的家庭背景之中，周围摆放着日常生活用品，以此营造出一种真实感，仿佛这些超凡事件就在眼前发生。"
   ],
