     "workCount": 1,
     "intro": [
      "弗朗西斯科·德·苏巴朗（1598-1664，巴达霍斯省丰特德坎托斯市-马德里），《圣佩德罗·诺拉斯科的异象》，1629年，来自王室收藏。",
      "这幅作品描绘的是13世纪圣佩德罗·诺拉斯科的房间内部。画中的圣佩德罗做了一个梦，在梦中天使向他展示了天上的城邦，即画作的背景。尽管场景带有丰富的意涵，却似乎只是圣佩德罗日常生活中的瞬间，17世纪风格的家具进一步强化了这一效果。",
      "画家巧妙地运用明暗对比，精细地描绘了衣物的褶皱。他还生动地传达了当时的人物情绪，尤其是对天使含蓄表情的处理。这幅作品曾是一家修道院装饰的组成部分，苏巴朗因经常接受此类委托，被誉为西班牙修道院生活画家中的佼佼者。"
     ],
