     "dims": "",
     "workCount": 1,
     "intro": [
      "弗朗西斯科·德·苏巴朗，《葡萄牙或阿拉贡的圣伊莎贝尔》，约1635年，来自王室收藏。",
      "苏巴朗是17世纪上半叶塞维利亚最杰出的画家之一，当时塞维利亚已成为西班牙版图中最为国际化的城市。在苏巴朗最优秀的作品中，对这类圣女形象的描绘尤为成功，而这幅画作属其中的上乘：画中的圣女以全身立像的形式出现，在微暗的背景中被强烈的光线照亮。她身着华丽的衣物，佩戴奢华的珠宝，双眼凝视着观者，仿佛正踏步向前。",
      "从她逼真的五官来看，画家很可能有一位真人模特。因此，这幅画还被解读为“神圣肖像”——也就是说，这可能是一位17世纪贵妇以圣人形象出现的画像，特别以花朵作为她的象征。"
     ],
