     "school": "文艺复兴（西班牙）",
     "medium": "木板油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "胡安·德·华内斯（约1503/1505-1579，巴伦西亚省拉丰特德拉菲格拉市-巴伦西亚省博凯伦特市），《大祭司亚伦》，约1545-1550年，来自王室收藏。",
      "这幅作品反映了文艺复兴时期西班牙画家胡安·德·华内斯受到的影响。观察画作，可以看到佛兰德斯绘画中的精湛技巧在此得以体现，尤其是在人物面部和物体（特别是罐子）的细节描绘上。同时，作品丰富艳丽的色彩和人物姿态的表现，显露出意大利绘画的影响，尤其是拉斐尔的绘画风格。"
     ],
