      "麦基洗德在多种宗教中备受尊崇，他既是头戴王冠的国王，又是手持面包和酒的祭司。这幅画与描绘亚伦的画作相邻，两者相得益彰。画作的金色背景，源于在红色粘土上层叠贴附的细小金箔，其中一些金箔在画板上部留有痕迹。"
