     "year": 1585,
     "yearLabel": "约 1585–1588 年",
     "school": "文艺复兴（意大利）",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "保罗·委罗内塞（1528-1588，维罗纳-威尼斯），《以撒的献祭》，约1585-1588年，来自王室收藏。",
      "在这类画作中，威尼斯画家往往着力强调情感的深度，并尽可能将场景中的人物简化至仅保留关键几位。因此，在这幅作品中，委罗内塞精心描绘了以撒之父亚伯拉罕的面部表情——天使降临时，他的面庞被阴影笼罩。此外，这幅画还反映出委罗内塞晚年对描绘风景的浓厚兴趣。"
     ],
