     "name": "以西结的异象：肉身复活",
     "artist": "弗朗西斯科·克朗特斯",
     "artistId": "collantes",
     "year": 1630,
     "yearLabel": "1630 年",
     "school": "西班牙巴洛克",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "弗朗西斯科·克朗特斯（约1599-约1656，马德里），《以西结的异象：肉身复活》，1630年，来自王室收藏。",
      "在这幅画作中，克朗特斯展现了他在风景和建筑画这一专长领域的非凡才能。画作下半部分所描绘的人物，是以西结所见的异象，其中融入了对古典时代的借鉴。这幅作品一直备受专家的赞赏，它于1811年被带到法国，在拿破仑希望于巴黎建立的博物馆中展出。"
     ],
