      "这幅画是巴伦西亚巴洛克艺术大师埃斯皮诺萨最杰出的作品之一。画作中紧凑的构图强化了瞬间的紧张感。画家巧妙地运用光线，特别照亮了主角，同时让其余一切都处于暗影之中，体现了卡拉瓦乔主义的美学风格。"
