     "workCount": 1,
     "intro": [
      "巴托洛梅·埃斯特万·牟利罗，《阿兰胡埃斯的圣灵受孕》，约1675-1680年，来自王室收藏。",
      "在16和17世纪，西班牙的文学家、雕塑家、画家及金银匠的创作都围绕着圣母的形象展开。牟利罗被认为是最能通过画作精准捕捉并表现这一主题的画家。他着重描绘圣母向上飞升的姿态，蓝色披风的飘动也有助于这一表现。普拉多博物馆收藏了五幅牟利罗创作的此类作品，这是最成熟且最具特色的其中之一，充分展现了牟利罗的绘画风格：笔法自如、轮廓线柔和、人物形象令观者倍感亲切。"
     ],
