     "dims": "",
     "workCount": 1,
     "intro": [
      "巴托洛梅·埃斯特万·牟利罗，《基督和圣母之间的圣奥古斯丁》，约1665年，来自王室收藏。",
      "牟利罗被誉为西班牙巴洛克时期最伟大的画家之一。他在创作大型宗教画作时，善于融入日常生活的细节。这一点可见于他对画作下方书籍的描绘以及对服饰绘制的处理。尽管画中的主人公生活在公元4世纪，但画家却选择为他披上17世纪的服装。"
     ],
