     "id": "e035",
     "order": 4,
     "name": "费尔南多六世和芭芭拉·德·布拉干萨在阿兰胡埃斯花园",
     "artist": "弗朗切斯科·巴塔格里奥利",
     "artistId": "battaglioli",
     "year": 1756,
     "yearLabel": "1756 年",
