     "id": "e037",
     "order": 6,
     "name": "哈巴涅拉舞",
     "artist": "曼努埃尔·罗德里格斯·德·古斯曼",
     "artistId": "guzman",
     "year": 1864,
     "yearLabel": "1864 年",
     "school": "浪漫主义",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "曼努埃尔·罗德里格斯·德·古斯曼（1818-1867，塞维利亚-马德里），《哈巴涅拉舞》，1864年，1865年购藏。",
      "浪漫主义时期，风俗画在塞维利亚流行起来。这些画作描绘了平民阶层的娱乐活动，画中人物身着反映其地区或职业的特色服饰。罗德里格斯·德·古斯曼是这一体裁的代表画家之一，他在1853年从塞维利亚迁居马德里后，继续致力于这一领域的创作。",
      "在马德里，他聚焦民间的风情习俗，比如这场哈巴涅拉舞。这是一种起源于古巴的音乐风格，其名称源自古巴首都哈瓦那。众多人物和各种色彩缤纷的服装，为画面增添了丰富的视觉效果。画家在运用光线上表现出独到的敏感度，总是巧妙地利用光影来突出画面的核心部分。"
     ],
