     "workCount": 1,
     "intro": [
      "彼得·保罗·鲁本斯及其工作室，《狩猎女神戴安娜》，约1620年，来自王室收藏。",
      "狩猎女神戴安娜头戴新月冠，在众仙女的簇拥下出现。与其他类似主题的绘画不同，本作并未直接描绘狩猎场面，而是展示了狩猎前的一刻。一位仙女吹响号角，宣告着行动即将开始。这幅画作出自鲁本斯及其工作室之手，而其中狗的形象，很可能是由动物画专家保罗·德·沃斯绘制的。",
      "鲁本斯与包括曼图亚公爵和费利佩四世在内的众多欧洲宫廷维持着紧密的联系。他卓越的社会地位和非凡的艺术才华，使其极具影响力。鲁本斯创作的肖像、宗教和神话主题作品，对多个画派产生了深远的影响。"
     ],
