     "id": "e040",
     "order": 3,
     "name": "劫夺希波达墨娅",
     "artist": "鲁本斯及其工作室",
     "artistId": "rubens",
     "year": 1636,
     "yearLabel": "1636–1637 年",
     "school": "佛兰德斯巴洛克",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "彼得·保罗·鲁本斯（1577-1640，锡根-安特卫普）及其工作室，《劫夺希波达墨娅》，1636-1637年，来自王室收藏。",
      "鲁本斯的绘画以运动感和群像描绘著称。在这幅画中他选择了奥维德《变形记》中最富戏剧性的时刻：在希波达墨娅和庇里托俄斯的婚宴上，半人马们喝醉了酒，试图劫持年轻的新娘希波达墨娅。画中人物的肌肉塑形和形体表达反映出鲁本斯对米开朗基罗作品的深刻理解。",
      "这幅画是帕拉达塔中最大尺幅的画作之一，帕拉达塔是专为国王们设立的狩猎行宫。与鲁本斯的其他画作一样，此作反映了人类的处境，以及半人马的兽性与人类的理性之间的斗争。"
     ],
