      "墨丘利是商业和旅行之神。在这幅画中，他左手握着双蛇杖，帽子和凉鞋均饰有羽翼，象征着他的敏捷。他的姿势让人联想到古典雕像，体现了当时最著名的画家鲁本斯对视觉元素的融合和应用。鲁本斯及其工作室为帕拉达塔创作了一系列装饰性画作，这幅作品就是其中之一。"
