      "在古代神话中，命运女神福尔图娜被描述为反复无常、难以捉摸。因此，在这幅画作中，她手持象征大海波涛汹涌、变幻无常的船帆，立于象征不稳定的球体之上。通过女神身体的刻画，鲁本斯展示了他对女性形象的感性和丰腴之美的独特演绎。"
