     "medium": "木板油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "老扬·勃鲁盖尔（1568-1625，布鲁塞尔-安特卫普），《花碗》，1615年，来自王室收藏。",
      "老扬·勃鲁盖尔作为佛兰德斯静物画的主要奠基人，擅长绘制生动逼真的花果装饰画和花卉画。他经常创作此类作品：一个深底陶制花碗盛放着各个季节的不同花朵，所有花卉都经由他的深入研究。通过将这些花卉聚集一处，他创造了一个色彩丰富且充满生机的理想画面。如桌上零星散落的花朵，仿佛刚从碗中掉落，这一细节巧妙地映射出自然的丰饶。"
     ],
