     "dims": "",
     "workCount": 1,
     "intro": [
      "胡安·范·德·哈曼-莱昂（1596-1631，马德里），《甜品和玻璃容器静物》，1622年，来自王室收藏。",
      "胡安·范·德·哈曼-莱昂是西班牙静物画萌芽期的标志性人物，这幅画是他最著名的佳作之一。作品采用了17世纪上半叶典型的构图风格，画面中不同的加工食物和与餐饮有关的物品被精心摆放在一张桌子或木板上。所有这些都井然有序地排列在简洁朴素的构图中，深色背景和巧妙的光影处理加强了物品的立体感，映射出玻璃器皿的光泽。"
     ],
