     "dims": "",
     "workCount": 1,
     "intro": [
      "胡安·费尔南德斯，又称“农人”（传）（据记载1630年至1636年活跃于马德里），《四串挂着的葡萄》，约1636年，2006年购藏。",
      "这位画家的生平虽鲜为人知，但他的画作在英国和西班牙宫廷备受赞誉。因此，他被视为最著名的静物画大师之一，因描绘葡萄而著称。其作品中的葡萄串通常置于深色背景前，通过光影交错营造一种错觉效果。展示了他在捕捉葡萄成熟阶段中微妙变化的才能。"
     ],
