     "intro": [
      "胡安·德·阿雷利亚诺（1614-1676，马德里自治区桑托尔卡斯市-马德里），《花环与景观》，1652年，由萨维·拉菲特于1930年捐赠。",
      "阿雷利亚诺是17世纪西班牙最杰出的花卉画家，深受尼德兰顶尖花卉大师的影响。他经常创作一些构思精妙的作品，比如这一幅：花环和雕刻框架将背景中的景观勾勒包裹其中。精心绘制的各式昆虫栖息于花朵之上，与精细描绘的花卉共同营造出一种视错觉。"
     ],
