     "intro": [
      "弗朗西斯科·德·戈雅-卢西恩特斯，《摘水果的男孩》，1778年，来自王室收藏。",
      "戈雅通过描绘孩子们的装束和破旧鞋履，精准捕捉了他们的质朴天性。他巧妙地呈现了孩子们脸上的各种情绪，一边是爬树者洋溢的喜悦，一边是等待用帽子接住果实者的忧心。作品描绘的画面，不仅反映了对命运深意的思考，也探讨了在追求超越身体极限时必须面对的风险。"
     ],
