     "intro": [
      "弗朗西斯科·德·戈雅-卢西恩特斯，《托比亚斯和天使》，约1787年，2003年购藏。",
      "戈雅的宗教题材作品既有为教堂设计的大型画作，也涵盖如这件作品那样，专为祈祷而绘制的小幅画作。从这幅画中，可以窥见他对古典雕塑的深入理解——尤其是天使的姿态和鞋履，令人联想到古罗马的雕塑。场景中的光影处理尤为出色，阳光洒满整个画面，与这位神圣人物的人性化形象形成了鲜明的对比。"
     ],
