     "dims": "",
     "workCount": 1,
     "intro": [
      "弗朗西斯科·德·戈雅-卢西恩特斯，《庆典当天的圣伊西德罗小教堂》，1788年，由佩德罗·费迪南·杜兰和贝尔纳多·德·奎罗斯于1931年遗赠。",
      "这件作品是挂毯画稿的初步草图，意在画稿完成之前呈献给国王以获得批准。因此，绘制手法较为简略。尽管如此，戈雅依然精妙地营造出作品的层次感，人物轮廓分明，足以辨识出其各自的社会阶层和表情。特别值得注意的是对光线的处理，夕阳的余晖将小教堂的部分区域映入阴影之中。这座教堂位于当时马德里的郊外，每年5月15日都会举行纪念圣伊西德罗的活动。人们聚集于此，享用“奇迹之水”，并在周边度过一天。"
     ],
