     "id": "e057",
     "order": 6,
     "name": "画家弗朗西斯科·巴耶乌",
     "artist": "弗朗西斯科·德·戈雅",
     "artistId": "goya",
     "year": 1795,
     "yearLabel": "1795 年",
     "school": "浪漫主义",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "弗朗西斯科·德·戈雅-卢西恩特斯，《画家弗朗西斯科·巴耶乌》，1795年，来自特立尼达博物馆。",
      "与之后浪漫主义倡导的理念相呼应，戈雅的创作力图捕捉人的主观感受和表现力。他被视为委拉斯开兹之后，西班牙艺术界最杰出的肖像画家。在这幅作品中，戈雅描绘了内兄——弗朗西斯科·巴耶乌，手持画笔的姿势暗示了其画家身份。",
      "两人的关系并非总是融洽，这也许解释了为什么戈雅通过冷色调和巴耶乌的面部表情来凸显人物性格。在此，戈雅展示了他对人性深刻的洞察力，以及在描绘细腻光泽效果和透明质感上的精湛技巧，特别是在外套的绘制上尤为显著。"
     ],
