     "name": "玛哈",
     "artist": "欧亨尼奥·卢卡斯·委拉斯开兹",
     "artistId": "lucas",
     "year": 1855,
     "yearLabel": "约 1855–1860 年",
     "school": "浪漫主义",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "欧亨尼奥·卢卡斯·委拉斯开兹（1817-1870，马德里），《玛哈》，约1855-1860年，由伊格纳西奥·祖洛加·扎巴莱塔于1932年捐赠。",
      "戈雅留下的作品数量众多，不仅为西班牙本土画家提供了灵感，也激发了国际舞台上一代又一代艺术家的创造力。卢卡斯便是戈雅的主要追随者，他不仅汲取了戈雅的题材，还在作品中融入了独特的个性化表达。他摒弃了原作中的批判和否定视角，将戈雅自由流畅的笔触转化得更为厚重而紧凑。在这幅作品中，女士们正在主持一场斗牛庆典，她们身着传统头纱、手持扇子，一位披着紫红色斗篷的斗牛士陪伴在侧。"
     ],
