     "intro": [
      "欧亨尼奥·卢卡斯·委拉斯开兹，《宗教裁判所的审判》，约1860年，1984年购藏。",
      "卢卡斯对戈雅笔下的若干主题进行了重新演绎，其中就包括这幅画作。当时，负责审判异端的宗教裁判所已不复存在，因此，卢卡斯的作品摒弃了批判性色彩，并将被定罪者骑在驴背上的形象与其他平易近人的人物进行并置，譬如作品前景中的马德里平民男子，这是戈雅时常描绘的对象。"
     ],
