     "id": "e060",
     "order": 1,
     "name": "萨宾娜·瑟芬姆·斯波尔丁",
     "artist": "费德里科·德·马德拉索-昆茨",
     "artistId": "madrazo",
     "year": 1846,
     "yearLabel": "1846 年",
     "school": "浪漫主义",
