     "dims": "",
     "workCount": 1,
     "intro": [
      "费德里科·德·马德拉索-昆茨（1815-1894，，罗马-马德里），《萨宾娜·瑟芬姆·斯波尔丁》，1846年，2014年购藏。",
      "马德拉索曾在罗马和巴黎学习绘画，并与安格尔结下了深厚的友谊，他的肖像画被视为西班牙浪漫主义时期的典范。肖像画往往揭示了画中人物的社会地位，并可能承载其他意义。红色天鹅绒的奢华和黑漆盒的精美突出了萨宾娜的经济地位——一位有名望的银行家之妻。书籍则暗示了她对文学的热爱，尤其是她与作家华盛顿·欧文的友谊。而花卉，特别是大丽花，象征永恒不变的爱情，紫杉树则意指长寿。"
     ],
