     "id": "e062",
     "order": 3,
     "name": "画家奥雷利亚诺·德·贝鲁埃特",
     "artist": "华金·索罗拉-巴斯蒂达",
     "artistId": "sorolla",
     "year": 1902,
     "yearLabel": "1902 年",
     "school": "印象主义",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "华金·索罗拉-巴斯蒂达（1863-1923，巴伦西亚-马德里塞尔塞迪利亚），《画家奥雷利亚诺·德·贝鲁埃特》，1902年，由玛丽亚·特蕾莎·莫雷特于1922年遗赠。",
      "华金·索罗拉是另一位伟大的肖像画家，他的作品在20世纪初的欧洲和美国极受推崇。奥雷利亚诺·德·贝鲁埃特（1845-1912年）不仅是索罗拉的挚友，亦是一位擅长绘制风景的画家。和其他作品一样，索罗拉在此处力图捕捉一个瞬间的形象，摒弃了同时代画家采用的刻板、静态的姿势。",
      "画中的贝鲁埃特呈现出一种自然而生动的姿态：手持帽子，外套未脱，头部转向观众，仿佛他刚进入室内，还来不及脱下外套和帽子。索罗拉的这种表现手法与自然主义绘画颇为接近，而其技巧则明显受到了委拉斯开兹的影响，他宽阔的笔触和对灰黑色调的精妙掌握都反映出这一点。"
     ],
