     "id": "e064",
     "order": 5,
     "name": "吉卜赛女郎",
     "artist": "雷蒙多·德·马德拉索-加雷特",
     "artistId": "madrazogarreta",
     "year": 1872,
     "yearLabel": "1872 年",
     "school": "现实主义",
     "medium": "布面油画",
     "dims": "",
     "workCount": 1,
     "intro": [
      "雷蒙多·德·马德拉索-加雷特（1841-1920，罗马-巴黎），《吉卜赛女郎》，1872年，由拉蒙·德·埃拉苏于1904年遗赠。",
      "费德里科·马德拉索之子雷蒙多的职业生涯主要在巴黎度过，他在那里成为一位备受推崇的画家。雷蒙多擅长肖像画和风俗画，前者令其名扬法国和美国。这幅独特的风俗画也尤为引人注目，是画家在塞维利亚之行期间创作的。从肤色和衣着可以看出画中描绘的是一位吉卜赛女郎。",
      "不同于其他吉卜赛主题作品，这幅画作避免了典型的刻板形象，内省的目光、沉浸式的姿态及人物的呈现方式，都表明这幅作品更贴近于肖像画而非一般的风俗再现。画家用极少的色彩创造出强烈的真实感，并捕捉到细微之处的精妙。"
     ],
