     "intro": [
      "罗莎·博纳尔（1822-1899，波尔多-托姆里），《狮子》，1879年，由欧内斯特·甘巴特于1879年捐赠。",
      "罗莎·博纳尔是当时最著名的女画家之一，她在动物绘画领域的杰出贡献彰显了这一时代的显著进步。博纳尔以动物画著称，自1870年起，她对老虎和狮子产生了浓厚的兴趣，尤其是本作中描绘的阿特拉斯狮。这头狮子的面部刻画之精细，几乎达到了人像画的水准，令人联想到西班牙的民族英雄熙德。因而，该作也被人们亲切地称为《熙德》。"
     ],
