     "intro": [
      "马里亚诺·福图尼-马萨尔（1838-1874，塔拉戈纳省雷乌斯市-罗马），《波尔蒂奇海滩上的男孩》，1874年，由拉蒙·德·埃拉苏于1904年遗赠。",
      "风俗画迎合了新兴资产阶级的审美趣味，福图尼在这一创作领域的成就尤为卓越。他以小画幅作品闻名，并对捕捉光影效果颇有研究。这幅画是艺术家的晚期杰作，创作地点是意大利那不勒斯附近的波尔蒂奇。",
      "艺术家在这一夏日户外的创作中首次尝试了海景画。该作品将对解剖学的深入探究和对光影效果的精妙捕捉完美结合，展现了对光线下人体的精准描绘以及特定身体部位色彩的巧妙运用。"
     ],
